  ('82470256-56c8-5a3c-bdb2-e38724a0d54b', null, (select id from public.skills where slug = 'write-g12-sentence-structure'), null, 'hard',
   $q$Which choice is grammatically complete?$q$, $q$[{"text":"That the river had shifted its course twice in a single century surprised the surveyors who compared the old maps.","is_correct":true},{"text":"The fact that the river had shifted its course twice in a single century, which surprised the surveyors comparing the old maps.","is_correct":false,"misconception_token":"relative-clause-fragment"},{"text":"The surveyors, comparing the old maps and surprised that the river had shifted its course twice in a single century.","is_correct":false,"misconception_token":"participle-fragment"},{"text":"Although the surveyors comparing the old maps were surprised that the river had shifted its course twice in a single century.","is_correct":false,"misconception_token":"subordinate-clause-fragment"}]$q$::jsonb, $q$That the river had shifted its course twice in a single century surprised the surveyors who compared the old maps.$q$, $q$The noun clause "That the river had shifted its course twice in a single century" is the subject, and "surprised" is the main verb. In the choice beginning "The fact that," the only verbs sit inside the "that" and "which" clauses, so "fact" never gets a main verb.$q$, 'draft', null)
